<script lang="ts">
 import {enhance} from '$app/forms';
 import AdvisoryValues from './AdvisoryValues.svelte';
 import {datedAdvisory,healthShares,riskItems,nutrientItems,irrigationDays,numberValue} from './advisory-model.mjs';
 let {record,date,product,enhanced,busy,topicId='',standalone=false}:{record:any,date:string,product:any,enhanced:any,busy:boolean,topicId?:string,standalone?:boolean}=$props();
 let selectedTopic=$state('health');
 let topic=$derived(topicId||selectedTopic);
 const headlines:Record<string,string>={health:'Understand your crop’s condition.',pests:'Know where to inspect.',weeds:'Follow potential weed pressure.',nutrients:'Review your nutrient guidance.',irrigation:'Plan water around your crop.',yield:'See the season’s yield outlook.',soil:'Understand your soil estimates.'};
 const topics=[['health','Crop health'],['pests','Pests & diseases'],['weeds','Weeds'],['nutrients','Nutrients'],['irrigation','Irrigation'],['yield','Yield outlook'],['soil','Soil insights']];
 let matches=$derived(product?.requestedDate===date);
 let dated=$derived(datedAdvisory(product,date));
 let advisory=$derived(dated?.advisory);
 let shares=$derived(healthShares(dated?.Satellite_Data));
 let risks=$derived(riskItems(advisory,topic));
 let nutrients=$derived(nutrientItems(advisory?.Fertilizer));
 let watering=$derived(irrigationDays(advisory?.Irrigation));
 let yieldData=$derived(advisory?.['Growth and Yield Estimation']);
 let soil=$derived(advisory?.['Soil Management']);
 const fmt=(v:any)=>numberValue(v)===null?'Unavailable':Number(v).toLocaleString('en',{maximumFractionDigits:2});
 const day=(v:string)=>`${v.slice(6)}/${v.slice(4,6)}/${v.slice(0,4)}`;
 let selected=$derived(topic==='pests'?advisory?.['Pest and Disease']:topic==='weeds'?advisory?.Weed:topic==='nutrients'?advisory?.Fertilizer:topic==='irrigation'?advisory?.Irrigation:topic==='yield'?advisory?.['Growth and Yield Estimation']:topic==='soil'?soil:dated?.Satellite_Data);
 let explanation=$derived(advisory?.['Explanation of calculated parameters']?.[({pests:'Pest & Disease',weeds:'Weed',nutrients:'Fertilizers',irrigation:'Irrigation',yield:'Growth and Yield Estimation',soil:'Soil Management'} as Record<string,string>)[topic]]);
</script>
<section class="p-card">
 <div class="p-section-heading"><div><p class="p-kicker">CROP INTELLIGENCE / FIELD ADVISORY</p><h2>{standalone?headlines[topic]:'From observation to inspection.'}</h2></div><form method="POST" action="?/report" use:enhance={enhanced}><input type="hidden" name="monitoring" value={record.id}/><input type="hidden" name="date" value={date||''}/><input type="hidden" name="kind" value="recommendations"/><button class="p-button" disabled={busy||!date||record.status!=='active'}>{matches?'Refresh advisory':'Generate field advisory'}</button></form></div>
 {#if !standalone}<div class="insight-tabs" role="group" aria-label="Advisory topics">{#each topics as [id,label]}<button type="button" class:chosen={topic===id} aria-pressed={topic===id} onclick={()=>selectedTopic=id}>{label}</button>{/each}</div>{/if}
 {#if advisory}
  <div class="context"><span>Farmonaut / JEEVN AI</span><span>Requested observation: {date}</span><span>Provider observation: {product.value.SensedDay||product.value.lastSatelliteVisit||'Not returned'}</span><span>Retrieved: {new Date(product.fetchedAt).toLocaleString('en-GB',{timeZone:'Africa/Harare'})}</span></div>
  {#if topic==='health'}<p>Provider satellite colour classifications are shown below. Refer to the dated image and index history for crop health; these values are not confirmed disease diagnoses.</p>{:else if topic==='pests'||topic==='weeds'}<p>Potential issues suggested by the provider. Inspect the crop to confirm presence before choosing a treatment.</p>{:else if topic==='nutrients'}<p>Estimated nutrient advice. These are not laboratory soil measurements. Application units are included exactly as supplied.</p>{:else if topic==='yield'}<p>A provider estimate, not a guaranteed harvest. Crop, planting date and local field conditions affect the result.</p>{:else if topic==='soil'}<p>Modelled soil properties for field review. Confirm pH, carbon and salinity with soil sampling.</p>{:else}<p>Provider watering guidance. Check the forecast, irrigation system and field moisture before applying water. Dates below are the provider’s dates.</p>{/if}
  {#if topic==='health'}
   <div class="health-total"><strong>{shares.find(v=>v.key==='green')?.percent??'?'}<small>%</small></strong><span>Healthy crop<br/><small>Provider colour classification</small></span></div>
   <div class="health-strip" aria-hidden="true">{#each shares as share}{#if share.percent!==null}<span class={share.key} style:flex-grow={share.percent}></span>{/if}{/each}</div>
   <div class="share-list">{#each shares as share}<div><span class="dot {share.key}"></span><span>{share.label}</span><strong>{share.percent===null?'Unavailable':share.percent+'%'}</strong></div>{/each}</div>
  {:else if topic==='pests'||topic==='weeds'}
   <div class="advice-label">{risks.length} potential {topic==='weeds'?'weeds':'pest / disease risks'} ? field confirmation needed</div>
   {#each risks as risk}<article class="risk-card"><div class="card-meta"><span>{risk.kind}</span><span>{risk.level} risk</span></div><h3>{risk.name}</h3><div class="risk-score"><span>Provider-estimated probability</span><strong>{risk.probability===null?'Not provided':risk.probability+'%'}</strong></div>{#if risk.probability!==null}<div class="risk-track"><span style:width={risk.probability+'%'}></span></div>{/if}{#if risk.solution}<details><summary>Provider treatment suggestions</summary><p class="note">Confirm the issue, local product approval and label instructions with your agronomist.</p><AdvisoryValues value={risk.solution}/></details>{/if}</article>{:else}<p>No potential risks were returned for this observation.</p>{/each}
  {:else if topic==='nutrients'}
   <div class="advice-label">Fertilizer product rates ? {advisory.Fertilizer?.application_rate_units||'units not returned'}</div>
   {#each nutrients as nutrient}<details class="nutrient-card"><summary><span class="element">{nutrient.code}</span><span><strong>{nutrient.name}</strong><small>{nutrient.level} priority</small></span><span class="dose">{fmt(nutrient.rate)}<small>{nutrient.unit}</small></span></summary><div class="nutrient-detail"><p><strong>Mineral product</strong><br/>{nutrient.source||'Source not provided'}</p><p><strong>Organic alternative</strong><br/>{fmt(nutrient.organicRate)} {nutrient.unit} ? {nutrient.organicSource||'Source not provided'}</p><p class="note">Alternatives are separate product recommendations. Review the provider?s application and splitting instructions before use.</p></div></details>{:else}<p>No nutrient rates were returned.</p>{/each}
   {#if advisory.Fertilizer?.frequency_of_application}<p class="note">Provider application frequency: every {advisory.Fertilizer.frequency_of_application} {advisory.Fertilizer.frequency_of_application_units||'(unit not provided)'}. Read the explanation for split doses and exceptions.</p>{/if}
  {:else if topic==='irrigation'}
   <div class="advice-label">Dated watering plan ? {advisory.Irrigation?.methods||'Method not provided'}</div>
   {#each watering as entry}<article class="watering-day" class:rest={entry.quantity===0}><div><strong>{day(entry.date)}</strong><small>{entry.time||'No time supplied'}</small></div><div class="dose">{entry.quantity===0?'No watering':fmt(entry.quantity)}<small>{entry.quantity===0?'Provider schedule':entry.unit}</small></div>{#if entry.methods.length}<details><summary>Methods & alternatives</summary><AdvisoryValues value={entry.methods}/></details>{/if}</article>{:else}<p>No watering dates were returned.</p>{/each}
   <a class="context-link" href="/portal/weather">Check the field forecast before watering ?</a>
  {:else if topic==='yield'&&yieldData}
   <article class="yield-card"><p>EXPECTED YIELD / PROVIDER ESTIMATE</p><strong>{fmt(yieldData.expected_yield_per_acre)}</strong><span>{yieldData.expected_yield_per_acre_units||'Unit not provided'}</span><div class="yield-range"><span>Local low<br/><b>{fmt(yieldData.potential_yield?.expected_local_minimum_yield)}</b></span><span>Local high<br/><b>{fmt(yieldData.potential_yield?.expected_local_maximum_yield)}</b></span></div><p class="note">Local range unit: {yieldData.potential_yield?.expected_yield_units||'not provided'}. This outlook is not a guaranteed harvest.</p></article>
   <div class="harvest-grid"><article><small>Harvest window</small><strong>{yieldData.expected_harvesting_period||'Not provided'}</strong></article><article><small>Harvest status</small><strong>{yieldData.harvest_status||'Not provided'}</strong></article></div>
  {:else if topic==='soil'&&soil}
   <div class="soil-grid">{#each [['pH',soil.pH,soil.pH_label],['Organic carbon',soil.SOC,soil.SOC_label],['Salinity',soil.salinity,'Provider estimate']] as [label,value,status]}<article><span>{label}</span><strong>{value??'Unavailable'}</strong><small>{status||'Not classified'}</small></article>{/each}</div><p class="note">These are provider estimates, not soil-test results. Organic carbon is shown on the provider?s supplied scale; consult the explanation for units and assumptions.</p>
  {:else if selected}<AdvisoryValues value={selected}/>{:else}<p>No information was returned for this topic.</p>{/if}
  {#if advisory.References}<details><summary>Sources & assumptions</summary><AdvisoryValues value={advisory.References[({health:'Soil Management',pests:'Pest & Disease',weeds:'Weed',nutrients:'Fertilizer',irrigation:'Irrigation',yield:'Growth and Yield Estimation',soil:'Soil Management'} as Record<string,string>)[topic]]||'No topic-specific source returned.'}/></details>{/if}
  {#if explanation}<details><summary>How the provider interprets this advice</summary><AdvisoryValues value={explanation}/></details>{/if}
 {:else}<div class="insight-empty"><h3>{topics.find(([id])=>id===topic)?.[1]} for your selected observation</h3><p>The dated advisory loads with the field view. Use Generate field advisory to request it again if needed. Missing or mismatched observations remain unavailable.</p></div>{/if}
</section>
