nt-card{border:1px solid #dce3d1;border-radius:11px;margin-top:12px;overflow:hidden}.nutrient-card summary{display:flex;align-items:center;gap:12px;padding:15px;cursor:pointer;list-style:none}.nutrient-card summary:after{content:'+';font-size:17px}.nutrient-card[open] summary:after{content:'?'}.element{display:grid;place-items:center;width:38px;height:38px;flex-shrink:0;border-radius:9px;background:#dfe9c8;font-size:17px;font-weight:700}.nutrient-card summary strong{font-size:12px}.nutrient-card small,.dose small{display:block;font-size:10px;color:#748069;margin-top:5px;font-weight:400}.dose{margin-left:auto;text-align:right;font-weight:700;font-size:17px}.nutrient-detail{padding:0 16px 15px;font-size:12px}.watering-day{display:flex;flex-wrap:wrap;align-items:center;gap:12px;padding:17px;border:1px solid #cddccc;background:#f0f5e8;border-radius:11px;margin:10px 0}.watering-day strong{font-size:12px}.watering-day small{display:block;font-size:10px;margin-top:5px;color:#6e7d66}.watering-day details{flex-basis:100%;font-size:11px;margin-top:0}.watering-day.rest{background:#f6f6ef;border-color:#e5e6db}.context-link{display:block;padding:15px 0;font-size:12px;font-weight:600}.yield-card{padding:24px 18px;background:#123f32;color:#fffef5;border-radius:12px;margin:18px 0}.yield-card>p:first-child{font-size:9px;letter-spacing:.12em;color:#c5d4ac}.yield-card>strong{display:block;font-size:46px;letter-spacing:-2px;font-weight:500}.yield-card>span{font-size:12px;color:#d7dfcc}.yield-range{display:flex;justify-content:space-between;gap:16px;border-top:6px solid #c8d6a0;margin-top:22px;padding-top:12px;font-size:10px}.yield-range span:last-child{text-align:right}.yield-card .note{color:#d1dcc5}.harvest-grid{display:grid;gap:12px;grid-template-columns:1fr 1fr}.harvest-grid article,.soil-grid article{padding:16px;border:1px solid #dce3d2;border-radius:10px}.harvest-grid small,.soil-grid span,.soil-grid small{display:block;font-size:10px;color:#6e7d68}.harvest-grid strong{display:block;font-size:13px;margin-top:9px;text-transform:capitalize}.soil-grid{display:grid;grid-template-columns:1fr;gap:12px;margin:20px 0}.soil-grid article{display:grid;grid-template-columns:1fr auto;gap:9px}.soil-grid strong{font-size:23px;grid-row:span 2}.soil-grid small{text-transform:capitalize}summary:focus-visible{outline:2px solid #b27d28;outline-offset:3px}</style>
